using namespace std;

using ll = long long;
using pii = pair<int, int>;
using pll = pair<ll, ll>;
using vi = vector<int>;
using vl = vector<ll>;
using vs = vector<string>;

const ll MOD = 1000000007LL;
const ll INF = 1000000000000000007LL;

inline ll gcd(ll a, ll b) {
    a = abs(a); b = abs(b);
    while (b != 0) {
        a %= b;
        swap(a, b);
    }
    return a;
}

inline ll lcm(ll a, ll b) {
    return a / gcd(a, b) * b;
}

inline void fast() {
    ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);
}

inline void print_double(int precision, double val) {
    cout << fixed << setprecision(precision) << val;
}

inline ll binpow(ll base, ll exp) {
    ll res = 1;
    while (exp > 0) {
        if (exp & 1) res = res * base;
        base = base * base;
        exp >>= 1;
    }
    return res;
}

void process_string(const string& input) {
    bool at_done = false;
    for (size_t i = 0; i < input.size(); ++i) {
        if (!at_done && i + 1 < input.size() && input[i] == 'a' && input[i+1] == 't' && i > 0 && i+1 < input.size()-1) {
            cout << '@';
            at_done = true;
            ++i;
        } else if (i + 2 < input.size() && input[i] == 'd' && input[i+1] == 'o' && input[i+2] == 't' && i > 0 && i+2 < input.size()-1) {
            cout << '.';
            i += 2;
        } else {
            cout << input[i];
        }
    }
}

int main() {
    fast();
    int test_cases = 1;
    // cin >> test_cases;
    for (int tc = 1; tc <= test_cases; ++tc) {
